# =============================================================================
# data.R  --  the simulated `shots` dataset (built by data-raw/shots.R).
# =============================================================================

#' Simulated shots
#'
#' A synthetic set of unblocked shot attempts between two fictional teams, generated by
#' `data-raw/shots.R` for examples and tests. Locations are plausible but invented, and
#' `xg` comes from a toy distance-and-angle model, not a fitted one. All shots are taken
#' towards the right-hand goal (the high-`x` end) of an [IIHF] rink, in metres with the
#' origin at the bottom-left corner of the boards.
#' @format A data frame with 1,500 rows and 8 columns:
#' \describe{
#'   \item{shot_id}{Shot id.}
#'   \item{game_id}{Game id, 1-10.}
#'   \item{period}{Period, 1-3.}
#'   \item{team}{Shooting team, `"Lakeside"` or `"Northfield"`.}
#'   \item{x, y}{Shot location, in metres.}
#'   \item{xg}{Expected-goal probability from the toy model.}
#'   \item{goal}{`1` if the shot was a goal, else `0`.}
#' }
#' @keywords datasets
"shots"

# after_stat(value) / after_stat(count) in geom_rink_bin() refer to the stat's output
# columns, which R CMD check can't see -- declare them so check stays NOTE-free.
utils::globalVariables(c("value", "count"))
